<template>
 <b-modal :visible="value" @change="$emit('input',$event)" @shown="opened" @hidden="closed" title="Buscar productos con IA" size="lg" hide-footer modal-class="pos-product-explorer-modal">
  <section class="product-explorer">
   <header><span>ALI · CONSULTA DE PRODUCTOS</span><h2>Conoce el producto antes de recomendarlo</h2><p>Características, imágenes, videos de YouTube y consejos de uso.</p></header>
   <form @submit.prevent="search()"><label for="product-explorer-query">Producto o modelo para consultar</label><div class="explorer-search"><input id="product-explorer-query" ref="queryInput" v-model="query" maxlength="300" required minlength="2" placeholder="Ej. impresora Epson L3250, laptop HP o sistema market" :disabled="busy"><button type="button" class="explorer-mic" :disabled="busy || !voiceSupported" :aria-pressed="listening" :title="voiceSupported?'Dictar nombre del producto':'Tu navegador no dispone de dictado'" @click="dictate"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/></svg><span>{{listening?'Detener':'Dictar'}}</span></button><button type="submit" class="explorer-submit" :disabled="busy || query.trim().length<2">Buscar con IA</button></div><small>Escribe o dicta el producto y pulsa Buscar con IA.</small></form>
   <p v-if="listening" class="explorer-status" role="status">Escuchando… {{interim}}</p><p v-if="voiceError" class="explorer-error" role="alert">{{voiceError}}</p>
   <div v-if="busy" class="explorer-status" role="status"><span>Consultando el producto y sus fuentes…</span><button type="button" @click="cancel">Cancelar búsqueda</button></div><p v-if="error" class="explorer-error" role="alert">{{error}}</p>
   <template v-if="result">
    <section class="explorer-overview"><span>{{cached?'CONSULTA RECIENTE':'RESULTADO DE LA CONSULTA'}}</span><h3>{{result.title}}</h3><p>{{result.summary}}</p><small v-if="result.exact_model">Modelo identificado: <b>{{result.exact_model}}</b></small></section>
    <nav class="explorer-sections" aria-label="Apartados de la consulta"><button v-for="item in sections" :key="item.key" type="button" :class="{active:section===item.key}" :aria-pressed="section===item.key" @click="selectSection(item.key)">{{item.label}}</button></nav>
    <section v-if="section!=='images' && section!=='videos'" class="explorer-detail"><h3>{{sectionTitle}}</h3><ul v-if="sectionItems.length"><li v-for="(item,i) in sectionItems" :key="i">{{item}}</li></ul><p v-else>No se encontraron datos comprobados para este apartado.</p></section>
    <section v-else-if="section==='images'" class="explorer-detail"><h3>Imágenes del catálogo y referencias</h3><p v-if="imagesBusy" role="status">Buscando imágenes en las fuentes consultadas…</p><div class="explorer-images"><article v-for="image in visibleImages" :key="image.url"><img :src="image.url" :alt="image.title" loading="lazy" referrerpolicy="no-referrer" @error="$set(failedImages,image.url,true)"><strong>{{image.title}}</strong><span v-if="image.catalog">Imagen del catálogo</span><a v-else :href="image.source" target="_blank" rel="noopener noreferrer">Ver origen de la imagen ↗</a></article></div><p v-if="!visibleImages.length &amp;&amp; !imagesBusy">No se encontraron imágenes disponibles para mostrar. Puedes revisar las páginas de las fuentes.</p><p class="explorer-image-note">Comprueba que la referencia visual corresponda al modelo que deseas ofrecer.</p></section>
    <section v-else class="explorer-detail explorer-video-section"><h3>Videos de referencia en YouTube</h3><p v-if="videosBusy" role="status">Buscando demostraciones y videos relacionados con el producto…</p><div v-if="videosError" class="explorer-error" role="alert">{{videosError}} <button type="button" @click="searchVideos">Intentar nuevamente</button></div><div class="explorer-videos"><article v-for="video in videos" :key="video.url"><span class="explorer-video-match" :class="video.match">{{videoMatch(video.match)}}</span><h4>{{video.title}}</h4><small v-if="video.channel">{{video.channel}}</small><p>{{video.reason}}</p><a :href="video.url" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" width="20" height="20" fill="currentColor" aria-hidden="true"><path d="M21.6 7.2a3 3 0 0 0-2.1-2.1C17.6 4.6 12 4.6 12 4.6s-5.6 0-7.5.5a3 3 0 0 0-2.1 2.1A31 31 0 0 0 2 12a31 31 0 0 0 .4 4.8 3 3 0 0 0 2.1 2.1c1.9.5 7.5.5 7.5.5s5.6 0 7.5-.5a3 3 0 0 0 2.1-2.1A31 31 0 0 0 22 12a31 31 0 0 0-.4-4.8M10 15.5v-7l6 3.5z"/></svg>Ver en YouTube ↗</a></article></div><p v-if="videosLoaded && !videos.length">No se encontraron videos de referencia para esta consulta.</p><p class="explorer-image-note">Las referencias generales pueden mostrar otra variante. Comprueba el modelo y las indicaciones del fabricante antes de aplicar el procedimiento.</p></section>
    <aside v-if="result.pending.length" class="explorer-pending"><strong>Por confirmar</strong><ul><li v-for="(item,i) in result.pending" :key="i">{{item}}</li></ul></aside>
    <details open v-if="result.sources.length" class="explorer-sources"><summary>Fuentes consultadas ({{result.sources.length}})</summary><ul><li v-for="source in result.sources" :key="source.url"><a :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title || source.url}}</a></li></ul></details>
   </template>
   <details v-if="catalog.length" class="explorer-catalog"><summary>Coincidencias en tu catálogo ({{catalog.length}})</summary><article v-for="product in catalog" :key="product.IdProducto"><div><strong>{{product.Producto}}</strong><small v-if="product.ProductoModelo">{{product.ProductoModelo}}</small></div><button type="button" :disabled="busy" @click="search(product)">Consultar este producto</button></article></details>
  </section>
 </b-modal>
</template>
<script>
export default {
 props:{value:Boolean},
 data(){return {query:'',busy:false,error:'',voiceError:'',listening:false,interim:'',result:null,catalog:[],images:[],imagesBusy:false,videos:[],videosBusy:false,videosLoaded:false,videosError:'',lookupToken:'',lookupCsrf:'',failedImages:{},cached:false,section:'characteristics',voiceSupported:!!(window.SpeechRecognition||window.webkitSpeechRecognition),sections:[{key:'characteristics',label:'Características'},{key:'uses',label:'Para qué sirve'},{key:'recommendations',label:'Recomendaciones'},{key:'images',label:'Imágenes'},{key:'videos',label:'Videos de YouTube'}]};},
 computed:{sectionTitle(){return (this.sections.find(s=>s.key===this.section)||this.sections[0]).label;},sectionItems(){return this.result?this.result[this.section]||[]:[];},visibleImages(){return this.images.filter(i=>!this.failedImages[i.url]);}},
 beforeDestroy(){this.closed();},
 methods:{
  opened(){this.$nextTick(()=>this.$refs.queryInput&&this.$refs.queryInput.focus());},
  closed(){this.cancel();this.stopDictation();},
  cancel(){this._sequence=(this._sequence||0)+1;if(this._request)this._request.abort();if(this._imagesRequest)this._imagesRequest.abort();if(this._videosRequest)this._videosRequest.abort();this.busy=false;this.imagesBusy=false;this.videosBusy=false;},
  stopDictation(){if(this._recognition){this._recognition.onresult=null;this._recognition.onerror=null;this._recognition.onend=null;this._recognition.abort();this._recognition=null;}this.listening=false;this.interim='';},
  dictate(){if(this.listening){this.stopDictation();return;}if(!this.voiceSupported||this.busy)return;this.voiceError='';this.interim='';const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;const recognition=new Speech();this._recognition=recognition;recognition.lang='es-PE';recognition.continuous=false;recognition.interimResults=true;recognition.onresult=event=>{if(this._recognition!==recognition)return;let final='',interim='';for(let i=event.resultIndex;i<event.results.length;i++){if(event.results[i].isFinal)final+=event.results[i][0].transcript;else interim+=event.results[i][0].transcript;}this.interim=interim;if(final.trim())this.query=final.trim().slice(0,300);};recognition.onerror=event=>{if(this._recognition!==recognition)return;this.voiceError=event.error==='not-allowed'?'Permite el acceso al micrófono para dictar el producto.':event.error==='no-speech'?'No se detectó voz. Puedes intentarlo otra vez.':'No se pudo completar el dictado. Puedes escribir el producto.';this.listening=false;};recognition.onend=()=>{if(this._recognition!==recognition)return;this.listening=false;this.interim='';this._recognition=null;};try{recognition.start();this.listening=true;}catch(e){this.voiceError='No se pudo iniciar el micrófono. Puedes escribir el producto.';this.stopDictation();}},
  async search(product=null){if(this.busy)return;if(product)this.query=product.Producto;if(this.query.trim().length<2)return;this.stopDictation();this.cancel();const sequence=this._sequence;this.error='';this.result=null;this.catalog=[];this.images=[];this.videos=[];this.videosLoaded=false;this.videosError='';this.lookupToken='';this.lookupCsrf='';this.failedImages={};this.section='characteristics';this.busy=true;const controller=new AbortController();this._request=controller;const timeout=setTimeout(()=>controller.abort(),115000);
   try{const configResponse=await fetch('/api/index.php/ali/config',{credentials:'same-origin',signal:controller.signal});const config=await configResponse.json();if(!configResponse.ok)throw Error(config.error||'Revisa tu sesión.');const response=await fetch('/api/index.php/ali/producto',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':config.csrf},signal:controller.signal,body:JSON.stringify({mode:'explore',query:this.query.trim(),product_id:product?Number(product.IdProducto):0})});const data=await response.json();if(sequence!==this._sequence)return;this.catalog=data.catalog||[];if(!response.ok)throw Error(data.error||'No se pudo consultar el producto.');if(!data.result||!['characteristics','uses','recommendations','pending','sources'].every(k=>Array.isArray(data.result[k])))throw Error('La respuesta llegó incompleta. Intenta nuevamente.');this.result=data.result;this.cached=!!data.cached;this.images=this.catalog.filter(p=>p.imageUrl).map(p=>({url:p.imageUrl,title:p.Producto,catalog:true}));this.lookupToken=data.imageLookup||'';this.lookupCsrf=config.csrf;if(data.imageLookup)this.searchImages(data.imageLookup,config.csrf,sequence);
   }catch(e){if(sequence===this._sequence)this.error=e.name==='AbortError'?'La consulta tardó demasiado. Intenta con el nombre y modelo exactos.':e.message;}finally{clearTimeout(timeout);if(sequence===this._sequence){this.busy=false;this._request=null;}}
  },
  selectSection(key){this.section=key;if(key==='videos'&&!this.videosLoaded)this.searchVideos();},
  videoMatch(match){return {exact:'Modelo exacto',family:'Misma familia',general:'Referencia general'}[match]||'Referencia general';},
  async searchVideos(){if(this.videosBusy)return;this.videosError='';if(!this.lookupToken){this.videosError='Vuelve a consultar el producto para buscar videos.';return;}const sequence=this._sequence;const controller=new AbortController();this._videosRequest=controller;this.videosBusy=true;const timeout=setTimeout(()=>controller.abort(),115000);try{const response=await fetch('/api/index.php/ali/producto',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':this.lookupCsrf},signal:controller.signal,body:JSON.stringify({mode:'explore_videos',token:this.lookupToken})});const data=await response.json();if(sequence!==this._sequence)return;if(!response.ok)throw Error(data.error||'No se pudieron buscar los videos.');if(!Array.isArray(data.videos))throw Error('La respuesta de videos llegó incompleta.');this.videos=data.videos.filter(v=>/^https:\/\/www\.youtube\.com\/watch\?v=[a-zA-Z0-9_-]{11}$/.test(v.url));this.videosLoaded=true;}catch(e){if(sequence===this._sequence)this.videosError=e.name==='AbortError'?'La búsqueda de videos tardó demasiado. Intenta nuevamente.':e.message;}finally{clearTimeout(timeout);if(sequence===this._sequence){this.videosBusy=false;this._videosRequest=null;}}},
  async searchImages(token,csrf,sequence){this.imagesBusy=true;const controller=new AbortController();this._imagesRequest=controller;const timeout=setTimeout(()=>controller.abort(),55000);try{const response=await fetch('/api/index.php/ali/producto',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Ali-CSRF':csrf},signal:controller.signal,body:JSON.stringify({mode:'explore_images',token})});const data=await response.json();if(sequence!==this._sequence||!response.ok)return;const seen=new Set(this.images.map(i=>i.url));for(const image of data.images||[])if(!seen.has(image.url)&&/^https?:\/\//i.test(image.url)&&/^https?:\/\//i.test(image.source)){this.images.push(image);seen.add(image.url);}}catch(e){}finally{clearTimeout(timeout);if(sequence===this._sequence){this.imagesBusy=false;this._imagesRequest=null;}}}
 }
};
</script>
<style scoped>
.product-explorer{font-family:Arial,sans-serif;color:#263b59}.product-explorer>header{padding:18px 20px;background:linear-gradient(115deg,#123d58,#443574);border-radius:10px;color:#fff;margin-bottom:20px}.product-explorer>header>span{font-size:10px;letter-spacing:1px;font-weight:700;color:#82e2ed}.product-explorer h2{font-size:21px;line-height:1.3;font-weight:800;margin:8px 0}.product-explorer>header p{font-size:13px;line-height:1.5;margin:0;color:#e6ebfa}.product-explorer form>label{display:block;font-size:13px;font-weight:700;margin-bottom:7px}.explorer-search{display:flex;gap:7px}.explorer-search input{flex:1;min-width:0;border:1px solid #c5d3e7;border-radius:7px;padding:12px;font-size:15px;color:#263b59}.product-explorer button{border:1px solid #c8d3e7;background:#fff;border-radius:7px;padding:10px 13px;font-size:12px;font-weight:700;color:#354c77;cursor:pointer}.product-explorer button:disabled{opacity:.5;cursor:default}.product-explorer button:focus-visible,.explorer-search input:focus-visible{outline:3px solid #a4b4ef;outline-offset:2px}.explorer-search .explorer-submit{background:#433591;color:#fff;border-color:#433591}.explorer-mic{display:flex;align-items:center;justify-content:center;gap:6px}.explorer-mic[aria-pressed=true]{color:#b31d3c;border-color:#d08a9a;background:#fff0f3}.product-explorer form>small{display:block;font-size:11px;color:#697b98;margin:8px 0}.explorer-status{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px;background:#eef4ff;color:#3d5582;border-radius:7px;font-size:13px;line-height:1.6;margin-top:12px}.explorer-error{padding:12px;background:#fff1f2;color:#a52c43;border:1px solid #efc7d0;border-radius:7px;font-size:13px;line-height:1.5}.explorer-overview{margin-top:20px;padding:18px;border:1px solid #d8e1ee;border-left:4px solid #4a3c91;border-radius:8px;background:#fbfcff}.explorer-overview>span{font-size:9px;letter-spacing:.8px;font-weight:800;color:#6d639b}.explorer-overview h3{font-size:18px;line-height:1.4;font-weight:800;margin:8px 0}.explorer-overview p{font-size:14px;line-height:1.65;margin:0 0 9px}.explorer-overview small{font-size:12px;color:#647694}.explorer-sections{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px;margin:16px 0}.explorer-sections button{padding:11px 6px;line-height:1.4}.explorer-sections .active{background:#433591;color:#fff;border-color:#433591}.explorer-detail{padding:17px 18px;border:1px solid #dce4ef;border-radius:8px;background:#fff}.explorer-detail h3{font-size:15px;font-weight:800;margin:0 0 12px}.explorer-detail ul,.explorer-pending ul{padding-left:20px;margin:0}.explorer-detail li{font-size:14px;line-height:1.65;padding:6px 0;border-bottom:1px solid #edf1f7;overflow-wrap:anywhere}.explorer-detail li:last-child{border-bottom:0}.explorer-detail p{font-size:13px;line-height:1.5}.explorer-images{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.explorer-images article{min-width:0;border:1px solid #e0e6f0;border-radius:8px;padding:10px;display:flex;flex-direction:column;gap:8px}.explorer-images img{width:100%;height:145px;object-fit:contain}.explorer-images strong{font-size:11px;line-height:1.4;overflow-wrap:anywhere}.explorer-images a,.explorer-images span{font-size:11px;line-height:1.4;color:#4b518f}.explorer-videos{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.explorer-videos article{display:flex;flex-direction:column;align-items:flex-start;padding:16px;border:1px solid #e5d5dc;border-top:3px solid #c82140;border-radius:9px;min-width:0;background:#fffafb}.explorer-videos h4{font-size:14px;line-height:1.5;font-weight:800;margin:10px 0 5px;overflow-wrap:anywhere}.explorer-videos small{font-size:11px;color:#65718a}.explorer-videos p{margin:10px 0 16px;line-height:1.6}.explorer-videos a{display:inline-flex;align-items:center;gap:7px;padding:9px 12px;background:#b71f38;border-radius:6px;color:#fff;font-size:12px;font-weight:700;margin-top:auto}.explorer-video-match{font-size:10px;font-weight:700;background:#eeeaf7;color:#574780;padding:5px 8px;border-radius:5px}.explorer-video-match.exact{background:#e1f4ed;color:#24614f}.explorer-video-match.family{background:#fff0d9;color:#835819}.explorer-image-note{font-size:11px!important;color:#74819a;margin:14px 0 0}.explorer-pending{padding:14px;border:1px solid #eddbc2;border-radius:8px;background:#fffbf3;font-size:12px;line-height:1.6;margin-top:14px}.explorer-pending strong{display:block;margin-bottom:6px}.explorer-sources,.explorer-catalog{margin:16px 0 0;padding:13px;border:1px solid #dce4ef;border-radius:8px;font-size:12px}.explorer-sources summary,.explorer-catalog summary{cursor:pointer;font-weight:700;color:#475a85}.explorer-sources ul{padding-left:18px;margin-top:10px}.explorer-sources li{padding:5px 0;overflow-wrap:anywhere}.explorer-sources a{color:#4b4192}.explorer-catalog article{display:flex;align-items:center;gap:10px;justify-content:space-between;padding:12px 0;border-bottom:1px solid #e8edf5}.explorer-catalog article:last-child{border:0}.explorer-catalog strong{display:block;line-height:1.5;font-size:12px}.explorer-catalog small{display:block;color:#6d7e98;margin-top:4px}.explorer-catalog button{flex-shrink:0;font-size:11px}@media(max-width:600px){.product-explorer>header{padding:15px}.product-explorer h2{font-size:18px}.explorer-search{flex-wrap:wrap}.explorer-search input{flex-basis:calc(100% - 100px)}.explorer-search .explorer-submit{width:100%;padding:12px}.explorer-sections{grid-template-columns:1fr 1fr}.explorer-images{grid-template-columns:1fr 1fr}.explorer-images img{height:110px}.explorer-detail{padding:13px}.explorer-catalog article{align-items:flex-start;flex-direction:column}.explorer-status{align-items:flex-start;flex-direction:column}}
</style>
<style>
.pos-product-explorer-modal .modal-dialog{width:calc(100% - 24px);max-width:960px;margin:25px auto}.pos-product-explorer-modal .modal-content{border-radius:12px;border:1px solid #cad7e7;overflow:hidden}.pos-product-explorer-modal .modal-header{background:#143850;color:#fff}.pos-product-explorer-modal .modal-header .close{color:#fff;opacity:1}.pos-product-explorer-modal .modal-title{font-weight:750;font-size:19px}.pos-product-explorer-modal .modal-body{max-height:calc(100vh - 155px);overflow-y:auto;padding:20px}@media(max-width:600px){.pos-product-explorer-modal .modal-dialog{margin:10px auto}.pos-product-explorer-modal .modal-body{max-height:calc(100dvh - 115px);padding:13px}}
</style>
